 30	import org.springframework.context.annotation.Configuration;
 31	import org.springframework.transaction.PlatformTransactionManager;
 32	
 33	
 34	/**
 35	 * 배송 상태 자동 업데이트를 위한 배치 작업 구성
 36	 */
 37	@Slf4j
 38	@Configuration
 39	@RequiredArgsConstructor
 40	public class UpdateShipmentStatusesJobConfig {
 41	
 42	    private final JobRepository jobRepository;
 43	    private final PlatformTransactionManager transactionManager;
 44	    private final EntityManagerFactory entityManagerFactory;
 45	
 46	    private final OrderShipmentRepository orderShipmentRepository;
 47	    private final NotificationCommandService notificationService;
 48	    private final OrderShipmentCommandService orderService;
 49	    private final CjTrackingPlaywright cjTrackingPlaywright;
 50	
 51	    private static final int CHUNK_SIZE = 50;
 52	    private static final int SKIP_LIMIT = 50;
 53	
 54	    @Bean
 55	    public Job updateShipmentStatusesJob() {
 56	        log.info("배송 상태 업데이트 작업 구성");
 57	        return new JobBuilder("updateShipmentStatusesJob", jobRepository)
 58	                .start(updateShipmentStatusesStep())
 59	                .build();
