   181	            String statusText = rows.last().select("td").get(4).text().trim();
   182	
   183	            if (statusText.isEmpty()) {
   184	                log.warn("배송 상태 텍스트가 비어 있음: 운송장={}", trackingNumber);
   185	                throw new ShipmentException(
   186	                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
   187	                        "배송 상태 정보를 찾을 수 없습니다."
   188	                );
   189	            }
   190	
   191	            return statusText;
   192	
   193	        } catch (IndexOutOfBoundsException e) {
   194	            log.error("HTML 파싱 중 인덱스 오류: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
   195	            throw new ShipmentException(
   196	                    ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
   197	                    "배송 상태 정보 파싱 실패: 예상한 형식과 다릅니다.",
   198	                    e
   199	            );
   200	        } catch (Exception e) {
   201	            if (e instanceof ShipmentException) {
   202	                throw (ShipmentException) e;
   203	            }
   204	
   205	            log.error("HTML 파싱 중 오류 발생: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
   206	            throw new ShipmentException(
   207	                    ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
   208	                    "배송 상태 정보 파싱 실패: " + e.getMessage(),
   209	                    e
   210	            );
   211	        }
   212	    }
