 10	    PREPARING, // 상품 준비 중
 11	    IN_WAREHOUSE, // 창고 보관 중
 12	    SHIPMENT_STARTED, // 배송 시작
 13	    IN_TRANSIT, // 배송 중
 14	    COMPLETED, // 배송 완료
 15	    REFUND_REQUESTED, // 환불 대기
 16	    REFUNDED; // 환불 완료
 17	
 18	    // 각 상태에서 전이 가능한 다음 상태들을 정의
 19	    private static final Map<OrderStatus, Set<OrderStatus>> ALLOWED_TRANSITIONS = new HashMap<>();
 20	
 21	    static {
 22	        // 상태 전이 규칙 초기화
 23	        ALLOWED_TRANSITIONS.put(PENDING_PAYMENT, Set.of(PAYMENT_COMPLETED, COMPLETED, IN_WAREHOUSE));
 24	        ALLOWED_TRANSITIONS.put(PAYMENT_COMPLETED, Set.of(PREPARING, REFUND_REQUESTED, IN_WAREHOUSE));
 25	        ALLOWED_TRANSITIONS.put(PREPARING, Set.of(IN_WAREHOUSE, SHIPMENT_STARTED));
 26	        ALLOWED_TRANSITIONS.put(IN_WAREHOUSE, Set.of(SHIPMENT_STARTED, COMPLETED));
 27	        ALLOWED_TRANSITIONS.put(SHIPMENT_STARTED, Set.of(IN_TRANSIT));
 28	        ALLOWED_TRANSITIONS.put(IN_TRANSIT, Set.of(COMPLETED));
 29	        ALLOWED_TRANSITIONS.put(REFUND_REQUESTED, Set.of(REFUNDED));
 30	        ALLOWED_TRANSITIONS.put(COMPLETED, Collections.emptySet());
 31	        ALLOWED_TRANSITIONS.put(REFUNDED, Collections.emptySet());
 32	    }
 33	
 34	    /**
 35	     * 현재 상태에서 새 상태로 전이가 가능한지 확인합니다.
 36	     *
 37	     * @param newStatus 전이하려는 새 상태
 38	     * @return 전이 가능 여부
 39	     */
 40	    public boolean canTransitionTo(OrderStatus newStatus) {
 41	        Set<OrderStatus> allowedNextStates = ALLOWED_TRANSITIONS.get(this);
 42	        return allowedNextStates != null && allowedNextStates.contains(newStatus);
 43	    }
 44	
 45	    /**
 46	     * 현재 상태에서 전이 가능한 모든 상태를 반환합니다.
 47	     *
 48	     * @return 전이 가능한 상태 집합
 49	     */
 50	    public Set<OrderStatus> getAllowedNextStates() {
 51	        return Collections.unmodifiableSet(ALLOWED_TRANSITIONS.getOrDefault(this, Collections.emptySet()));
 52	    }
 53	}
