  1	     *
  2	     * @param orderId 주문 ID
  3	     * @param userEmail 사용자 이메일
  4	     * @param requestDto 결제 및 배송 요청 정보
  5	     * @throws OrderNotFoundException 주문을 찾을 수 없는 경우
  6	     * @throws OrderAccessDeniedException 주문에 대한 접근 권한이 없는 경우
  7	     * @throws OrderPaymentProcessingFailedException 결제 처리 실패 시
  8	     * @throws OrderShipmentProcessingFailedException 배송 처리 실패 시
  9	     * @throws OrderWarehouseStorageProcessingFailedException 창고 보관 처리 실패 시
 10	     * @throws InvalidPaymentShipmentDataException 결제 및 배송 정보가 유효하지 않은 경우
 11	     */
 12	    @Transactional
 13	    public void processPaymentAndShipment(Long orderId, String userEmail, PayAndShipmentRequestDto requestDto) {
 14	        if (orderId == null) {
 15	            throw new InvalidOrderDataException("주문 ID가 없습니다.");
 16	        }
 17	        if (userEmail == null || userEmail.trim().isEmpty()) {
 18	            throw new OrderAccessDeniedException("사용자 정보가 없습니다.");
 19	        }
 20	        if (requestDto == null) {
 21	            throw new InvalidPaymentShipmentDataException("결제 및 배송 정보가 없습니다.");
 22	        }
 23	
 24	        try {
 25	            // 1. User 및 Order 조회
 26	            User user = userQueryService.findByEmail(userEmail);
 27	            Order order = orderRepository.findById(orderId)
 28	                    .orElseThrow(() -> new OrderNotFoundException("해당 주문을 찾을 수 없습니다(ID: " + orderId + ")"));
 29	
 30	            // 접근 권한 확인
 31	            if (!order.getUser().getId().equals(user.getId())) {
 32	                throw new OrderAccessDeniedException("해당 사용자는 이 주문을 처리할 권한이 없습니다.");
 33	            }
 34	
 35	            // 주문 정보 유효성 검사
 36	            validatePaymentShipmentRequest(requestDto);
 37	
 38	            try {
 39	                // 2. 결제 처리
 40	                Payment payment = paymentCommandService.processPayment(order, user, requestDto.getPaymentRequest());
 41	                order.assignPayment(payment);
 42	            } catch (Exception e) {
 43	                log.error("결제 처리 중 오류 발생: {}", e.getMessage(), e);
 44	                throw new OrderPaymentProcessingFailedException("결제 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
 45	            }
 46	
 47	            try {
 48	                // 3. 배송 정보 생성
 49	                OrderShipment shipment = orderShipmentCommandService.createOrderShipment(
 50	                        order,
 51	                        requestDto.getReceiverName(),
 52	                        requestDto.getReceiverPhone(),
 53	                        requestDto.getPostalCode(),
 54	                        requestDto.getAddress()
 55	                );
 56	                order.assignOrderShipment(shipment);
 57	            } catch (Exception e) {
 58	                log.error("배송 정보 처리 중 오류 발생: {}", e.getMessage(), e);
 59	                throw new OrderShipmentProcessingFailedException("배송 정보 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
 60	            }
 61	
 62	            try {
 63	                // 4. 상태 업데이트
 64	                if (requestDto.isWarehouseStorage()) {
 65	                    // 창고 보관일 경우
 66	                    order.updateStatus(OrderStatus.PAYMENT_COMPLETED);
 67	                    order.updateStatus(OrderStatus.PREPARING);
 68	                    order.updateStatus(OrderStatus.IN_WAREHOUSE);
 69	
 70	                    // 창고 보관 처리 추가
 71	                    WarehouseStorage warehouseStorage = warehouseStorageCommandService.createOrderStorage(order, user);
 72	                    order.assignWarehouseStorage(warehouseStorage);
 73	                    order.updateStatus(OrderStatus.COMPLETED);  // 주문 완료 상태로 변경
 74	                } else {
 75	                    // 실제 배송일 경우
 76	                    order.updateStatus(OrderStatus.PAYMENT_COMPLETED);
 77	                    order.updateStatus(OrderStatus.PREPARING);
 78	                }
 79	            } catch (WarehouseStorageException e) {
 80	                log.error("창고 보관 처리 중 오류 발생: {}", e.getMessage(), e);
 81	                throw new OrderWarehouseStorageProcessingFailedException("창고 보관 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
 82	            } catch (Exception e) {
 83	                log.error("주문 상태 업데이트 중 오류 발생: {}", e.getMessage(), e);
 84	                throw new OrderStatusUpdateFailedException("주문 상태 업데이트 중 오류가 발생했습니다: " + e.getMessage(), e);
 85	            }
 86	
 87	            // 5. OrderBid 상태 업데이트
 88	            try {
 89	                orderBidQueryService.findById(orderId).ifPresent(orderBid -> {
 90	                    orderBid.updateStatus(BidStatus.MATCHED);
 91	                });
 92	            } catch (Exception e) {
 93	                log.error("주문 입찰 상태 업데이트 중 오류 발생: {}", e.getMessage(), e);
 94	                // 중요 정보 처리가 완료되었으므로 예외를 던지지 않고 로그만 남김
 95	            }
 96	        } catch (Exception e) {
 97	            if (e instanceof OrderException) {
 98	                throw e;
 99	            }
100	            log.error("결제 및 배송 처리 중 오류 발생: {}", e.getMessage(), e);
101	            throw new OrderPaymentProcessingFailedException("결제 및 배송 처리 중 예상치 못한 오류가 발생했습니다: " + e.getMessage(), e);
102	        }
103	    }
104	
105	    /**
106	     * 즉시 구매 주문을 생성합니다.
107	     *
108	     * @param buyer 구매자 정보
109	     * @param saleBid 판매 입찰 정보
110	     * @param addressId 배송지 ID
111	     * @param isWarehouseStorage 창고 보관 여부
112	     * @param paymentRequest 결제 요청 정보
113	     * @return 생성된 주문
114	     * @throws OrderCreationFailedException 주문 생성 실패 시
115	     * @throws SaleBidNotFoundException 판매 입찰을 찾을 수 없는 경우
116	     * @throws InvalidOrderDataException 주문 정보가 유효하지 않은 경우
        handleOrderProcessingEvent(event, acknowledgment);

