private SaleBid getSaleBidAndValidate(Long saleBidId) {
    SaleBid saleBid = saleBidQueryService.findById(saleBidId);
    if (saleBid == null) {
        throw new SaleBidNotFoundException("판매 입찰을 찾을 수 없습니다(ID: " + saleBidId + ")");
    }

    Sale sale = saleBid.getSale();
