    } catch (Exception e) {
        if (e instanceof OrderException) {
            throw e;
        }
        log.error("주문 입찰 매칭 중 오류 발생: {}", e.getMessage(), e);
        throw new OrderBidMatchingFailedException("주문 입찰 매칭 중 오류가 발생했습니다: " + e.getMessage(), e);
    }
}

